
# ============================
# STRATIQA V14 DESIGN NOTES
# - Premium Inter/Geist typography
# - Refined sidebar spacing
# - Premium bordered navigation
# - Larger statistic typography
# - Cleaner confidence rings
# - Apple/Linear inspired visual polish
# ============================

#requires -Version 5.1
$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

function Write-Stage([string]$Message) { Write-Host "`n==> $Message" -ForegroundColor Cyan }
function Write-Ok([string]$Message) { Write-Host "[OK] $Message" -ForegroundColor Green }
function Write-Warn([string]$Message) { Write-Host "[WARN] $Message" -ForegroundColor Yellow }

$Root = (Get-Location).Path
$PackagePath = Join-Path $Root "package.json"
$Utf8NoBom = New-Object System.Text.UTF8Encoding($false)

if (-not (Test-Path $PackagePath)) { throw "Run this installer from the STRATIQA project root beside package.json." }
if (-not (Test-Path (Join-Path $Root "src\app"))) { throw "Expected src\app was not found." }

$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupRoot = Join-Path $Root "stratiqa-backups\v14-$Timestamp"
New-Item -ItemType Directory -Force -Path $BackupRoot | Out-Null
$Created = New-Object System.Collections.Generic.List[string]
$BackedUp = New-Object System.Collections.Generic.List[string]

function Backup-Target([string]$RelativePath) {
  $FullPath = Join-Path $Root $RelativePath
  if (Test-Path $FullPath) {
    $Destination = Join-Path $BackupRoot $RelativePath
    New-Item -ItemType Directory -Force -Path (Split-Path $Destination -Parent) | Out-Null
    Copy-Item -LiteralPath $FullPath -Destination $Destination -Force
    $BackedUp.Add($RelativePath) | Out-Null
  } else {
    $Created.Add($RelativePath) | Out-Null
  }
}

function Put-Base64([string]$RelativePath,[string]$Content) {
  Backup-Target $RelativePath
  $FullPath = Join-Path $Root $RelativePath
  New-Item -ItemType Directory -Force -Path (Split-Path $FullPath -Parent) | Out-Null
  $Text = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Content))
  [System.IO.File]::WriteAllText($FullPath,$Text,$Utf8NoBom)
  Write-Ok "Updated $RelativePath"
}

function Restore-All {
  Write-Warn "Restoring files changed by V14..."
  foreach ($RelativePath in $Created) {
    $FullPath = Join-Path $Root $RelativePath
    if (Test-Path $FullPath) { Remove-Item -LiteralPath $FullPath -Force -ErrorAction SilentlyContinue }
  }
  foreach ($RelativePath in $BackedUp) {
    $Source = Join-Path $BackupRoot $RelativePath
    $Destination = Join-Path $Root $RelativePath
    New-Item -ItemType Directory -Force -Path (Split-Path $Destination -Parent) | Out-Null
    Copy-Item -LiteralPath $Source -Destination $Destination -Force
  }
  Remove-Item -Recurse -Force (Join-Path $Root ".next") -ErrorAction SilentlyContinue
}

Write-Host ""
Write-Host "============================================================" -ForegroundColor Cyan
Write-Host " STRATIQA INSTALLER V14 - PREMIUM DESIGN LANGUAGE" -ForegroundColor White
Write-Host "============================================================" -ForegroundColor Cyan
Write-Host "Backup: $BackupRoot" -ForegroundColor DarkGray

try {
  Write-Stage "Validating project and normalizing package.json"
  $PackageText = [System.IO.File]::ReadAllText($PackagePath).TrimStart([char]0xFEFF)
  $null = $PackageText | ConvertFrom-Json
  Backup-Target "package.json"
  [System.IO.File]::WriteAllText($PackagePath,$PackageText,$Utf8NoBom)
  Write-Ok "package.json is valid"

  Write-Stage "Installing V14.1 component replacements, centered navigation, rebuilt Matchups, system-font typography, and mockup-aligned design language"
  Put-Base64 "src\components\shared\PremiumConfidenceRing.tsx" ""
  Put-Base64 "src\components\layout\Sidebar.tsx" ""
  Put-Base64 "src\components\dashboard\V11IntelligenceDashboard.tsx" ""
  Put-Base64 "src\app\dashboard\page.tsx" "aW1wb3J0IFYxMUludGVsbGlnZW5jZURhc2hib2FyZCBmcm9tICJAL2NvbXBvbmVudHMvZGFzaGJvYXJkL1YxMUludGVsbGlnZW5jZURhc2hib2FyZCI7CgpleHBvcnQgZGVmYXVsdCBmdW5jdGlvbiBEYXNoYm9hcmRQYWdlKCkgewogIHJldHVybiA8VjExSW50ZWxsaWdlbmNlRGFzaGJvYXJkIC8+Owp9Cg=="

  Write-Stage "Installing V14 premium visual system"
  Put-Base64 "src\app\matchups\page.tsx" ""

  $CssPath = Join-Path $Root "src\app\globals.css"
  Backup-Target "src\app\globals.css"
  $ExistingCss = if (Test-Path $CssPath) { [System.IO.File]::ReadAllText($CssPath) } else { "" }
  $StartMarker = "/* STRATIQA V11 INTELLIGENCE LAYER START */"
  $EndMarker = "/* STRATIQA V11 INTELLIGENCE LAYER END */"
  $StartIndex = $ExistingCss.IndexOf($StartMarker)
  if ($StartIndex -ge 0) {
    $EndIndex = $ExistingCss.IndexOf($EndMarker,$StartIndex)
    if ($EndIndex -ge 0) {
      $EndIndex += $EndMarker.Length
      $ExistingCss = $ExistingCss.Remove($StartIndex,$EndIndex-$StartIndex)
    }
  }
  $V11Css = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(""))
  $V14StructuralCss = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(""))
  [System.IO.File]::WriteAllText($CssPath,$ExistingCss.TrimEnd()+"`r`n`r`n"+$V11Css+"`r`n`r`n"+$V14StructuralCss+"`r`n",$Utf8NoBom)
  Write-Ok "Updated src\app\globals.css with V14 structural refinement"

  Write-Stage "Updating GitHub build workflow"
  Put-Base64 ".github\workflows\build.yml" ""

  Write-Stage "Verifying dependencies"
  if (-not (Test-Path (Join-Path $Root "node_modules"))) {
    if (Test-Path (Join-Path $Root "package-lock.json")) { npm ci } else { npm install }
    if ($LASTEXITCODE -ne 0) { throw "Dependency installation failed with exit code $LASTEXITCODE." }
  }

  Write-Stage "Running production build validation"
  Remove-Item -Recurse -Force (Join-Path $Root ".next") -ErrorAction SilentlyContinue
  npm run build
  if ($LASTEXITCODE -ne 0) { throw "npm run build returned exit code $LASTEXITCODE." }

  Write-Host ""
  Write-Host "============================================================" -ForegroundColor Green
  Write-Host " STRATIQA V14 INSTALLED SUCCESSFULLY" -ForegroundColor White
  Write-Host "============================================================" -ForegroundColor Green
  Write-Host "Dashboard: http://localhost:3000/dashboard" -ForegroundColor Gray
  Write-Host "Profile: http://localhost:3000/analysts/heriberto" -ForegroundColor Gray
  Write-Host "Community: http://localhost:3000/community" -ForegroundColor Gray
  Write-Host "Friends: http://localhost:3000/friends" -ForegroundColor Gray
  Write-Host "Leaderboard: http://localhost:3000/leaderboard" -ForegroundColor Gray
  Write-Host "Run: npm run dev" -ForegroundColor Yellow
  Write-Host "Backup retained at: $BackupRoot" -ForegroundColor DarkGray
}
catch {
  $Failure = $_.Exception.Message
  Write-Host "`nV14 installation failed: $Failure" -ForegroundColor Red
  Restore-All
  Write-Host "Your pre-V14 files were restored from: $BackupRoot" -ForegroundColor Yellow
  exit 1
}
